style.css:
@-moz-document domain("google.com") {
/* --- Fondo principal y color de texto --- */
  body {
    background: url("https://24.media.tumblr.com/11036cdf8c67e7d970b681dfbf7d6d29/tumblr_mojslfV6CE1rat1m0o1_500.gif") no-repeat fixed !important;
    background-size: cover !important;
    color: #161616 !important;
  }

  /* --- Ocultar elementos de Google --- */
  #hplogo,
  #fbar,
  #footer,
  .logo-subtext,
  .gb_gf,
  #prm-pt [aria-label="promo"] {
    display: none !important;
  }

  /* --- Colores de enlaces --- */
  a:link { color: #000000 !important; }
  a:visited { color: #A0A0A0 !important; }

  /* --- Selección de texto --- */
  ::selection { background-color: #FFFFFF !important; color: #000000 !important; }
  ::-moz-selection { background-color: #FFFFFF !important; color: #000000 !important; }

  /* --- Logo "Your Name" en la home --- */
  body.hp #lga {
    background: url("https://upload.wikimedia.org/wikipedia/commons/4/4b/Your_name_movie_logo.png") no-repeat center 109px !important;
    background-size: 272px 92px !important;
  }

  /* --- Logo monocromo de Google --- */
  #logo,
  #logocont {
    background: url("https://vignette.wikia.nocookie.net/logopedia/images/f/f7/2000px-Google_2015_monochrome.svg.png/revision/latest?cb=20150901175304") no-repeat center !important;
    background-size: 92px 30px !important;
  }

  #logo > *,
  #logocont > * {
    opacity: 0 !important;
  }

  /* --- Botones e íconos invertidos --- */
  .jfk-button-img {
    filter: invert(1) hue-rotate(180deg);
    -webkit-filter: invert(1) hue-rotate(180deg);
  }

  #gbwa > div:first-child > a,
  #gbwa + div a > div {
    background-image: url("http://ssl.gstatic.com/gb/images/v1_76783e20.png") !important;
    background-size: 92px 2541px !important;
  }

  #gbwa > div:first-child > a { background-position: -60px -1675px !important; }
  #gbwa + div a > div {
    background-color: rgba(255,255,255,0.55) !important;
    background-position: -92px -1921px !important;
  }
}
